-- YAM APP — SEED DATA v2  (Project ZERO 5-Year Survey — full synthetic dataset)
-- Supersedes supabase-seed.sql.  Run AFTER: schema, migration-001, migration-002.
-- Safe to re-run: deletes existing Project ZERO data, then re-inserts.
-- Circular FK strategy: COs inserted first (approval_id=NULL, defect_record_id=NULL),
-- defects inserted second (change_order_id=NULL), approvals third,
-- then UPDATE both tables to wire the back-references.
-- ─────────────────────────────────────────────────────────────────────────────────

-- ─── CLEAN EXISTING PROJECT ZERO DATA ────────────────────────────────────────────
DELETE FROM world_model_events WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM documents           WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM project_members     WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM owner_approvals     WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
UPDATE change_orders SET defect_record_id = NULL, approval_id = NULL
  WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM change_orders       WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
UPDATE defect_records SET change_order_id = NULL
  WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM defect_records      WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM inspection_events   WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM work_packages        WHERE project_id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM projects WHERE id = 'a1b2c3d4-0002-0000-0000-000000000001';
DELETE FROM vessels  WHERE id = 'a1b2c3d4-0001-0000-0000-000000000001';

