-- ─── BACK-FILL CIRCULAR FKs ─────────────────────────────────────────────────────────────────────────────
-- Wire change_orders → defect_records and change_orders → owner_approvals
UPDATE change_orders SET
  defect_record_id = 'a1b2c3d4-0030-0000-0000-000000000001',
  approval_id      = 'a1b2c3d4-0050-0000-0000-000000000001'
WHERE id = 'a1b2c3d4-0040-0000-0000-000000000001';

UPDATE change_orders SET
  defect_record_id = 'a1b2c3d4-0030-0000-0000-000000000003',
  approval_id      = 'a1b2c3d4-0050-0000-0000-000000000002'
WHERE id = 'a1b2c3d4-0040-0000-0000-000000000002';

UPDATE change_orders SET
  defect_record_id = 'a1b2c3d4-0030-0000-0000-000000000005',
  approval_id      = 'a1b2c3d4-0050-0000-0000-000000000003'
WHERE id = 'a1b2c3d4-0040-0000-0000-000000000003';

-- Wire defect_records → change_orders
UPDATE defect_records SET change_order_id = 'a1b2c3d4-0040-0000-0000-000000000001'
WHERE id = 'a1b2c3d4-0030-0000-0000-000000000001';

UPDATE defect_records SET change_order_id = 'a1b2c3d4-0040-0000-0000-000000000002'
WHERE id = 'a1b2c3d4-0030-0000-0000-000000000003';

UPDATE defect_records SET change_order_id = 'a1b2c3d4-0040-0000-0000-000000000003'
WHERE id = 'a1b2c3d4-0030-0000-0000-000000000005';

