INSERT INTO project_members (id,project_id,user_id,role,name,email,company,created_at) VALUES
  ('a1b2c3d4-0070-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001',NULL,'OWNERS_REP',   'Nadir',               'nadir@yam.limited',            'YAM.Limited',         '2026-01-15T00:00:00Z'),
  ('a1b2c3d4-0070-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001',NULL,'OWNER',        'Alexander Fontaine',  'alex@fontaine-family.com',     'Fontaine Family Office','2026-01-15T00:00:00Z'),
  ('a1b2c3d4-0070-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001',NULL,'CAPTAIN',      'Captain James Harlow','captain@projectzero.com',      NULL,                  '2026-01-15T00:00:00Z'),
  ('a1b2c3d4-0070-0000-0000-000000000004','a1b2c3d4-0002-0000-0000-000000000001',NULL,'YARD_PM',      'Sarah Mitchell',      'sarah.mitchell@pendennis.com', 'Pendennis Shipyard',  '2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0070-0000-0000-000000000005','a1b2c3d4-0002-0000-0000-000000000001',NULL,'CLASS_SURVEYOR','Marco Ferretti',     'm.ferretti@rina.org',          'RINA',                '2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0070-0000-0000-000000000006','a1b2c3d4-0002-0000-0000-000000000001',NULL,'YARD_PM',      'Tom Bradley',         't.bradley@pendennis.com',      'Pendennis Shipyard',  '2026-01-20T00:00:00Z'),
