  ('a1b2c3d4-0070-0000-0000-000000000008','a1b2c3d4-0002-0000-0000-000000000001',NULL,'SUBCONTRACTOR','Paulo Mendes',        'p.mendes@marintek.it',         'Marintek Acciaio',    '2026-02-15T00:00:00Z')
INSERT INTO work_packages (id,project_id,wp_number,title,discipline,description,status,planned_hours,actual_hours,planned_cost,actual_cost,trade_contractor,planned_start,planned_end,actual_start,actual_end,is_class_item,class_society,class_item_ref,created_at) VALUES
  ('a1b2c3d4-0010-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001','WP-CLASS-001','RINA 5-Year Special Survey','CLASS','Full 5-year special survey per RINA rules. Includes initial condition survey, survey programme agreement, structural sampling plan, and class renewal certificate.','SCOPED',240,0,48000,0,'RINA Surveyor','2026-05-05','2026-07-30',NULL,NULL,true,'RINA','RINA-5YS-2026','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001','WP-CLASS-002','Ultrasonic Thickness Gauging Programme','CLASS','Full hull and structural UT gauging per RINA requirements. Minimum 200 measurement points covering plating, frames, longitudinals, and bulkheads. Report submitted to class surveyor for acceptance.','ACTIVE',120,38,24000,9500,'Marintek Acciaio','2026-04-15','2026-05-10','2026-04-15',NULL,true,'RINA','RINA-UTG-001','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001','WP-HULL-001','Hull Blasting & Antifouling Application','HULL','Full hull blasting to Sa 2.5, two-coat epoxy primer (2x125 micron DFT), and application of Jotun SeaQuantum Ultra S antifouling. Includes sea chest cleaning and zinc anode fitment.','SCOPED',480,0,85000,0,'Pendennis Coatings','2026-05-15','2026-06-10',NULL,NULL,false,NULL,NULL,'2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000004','a1b2c3d4-0002-0000-0000-000000000001','WP-STRUCT-001','Structural Weld Inspection & Remediation','STRUCTURAL','MPI inspection of all structural welds in engine room, bilge frames, mast step, and keel area per RINA requirements. Remediate any identified cracks or corrosion. Currently ON HOLD pending NCR-001 assessment.','ON_HOLD',120,8,22000,1200,'Pendennis Structural','2026-05-10','2026-05-22','2026-04-30',NULL,true,'RINA','RINA-ST-005','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000005','a1b2c3d4-0002-0000-0000-000000000001','WP-STRUCT-002','Frame Replacement — Stations 47-49 (NCR-2026-001)','STRUCTURAL','Full replacement of portside longitudinal frames at stations 47, 48, and 49 following CRITICAL corrosion finding NCR-2026-001. New frames to original scantlings. RINA witness inspection required at completion.','EXPANDED',280,0,47200,0,'Marintek Acciaio','2026-05-20','2026-06-15',NULL,NULL,true,'RINA','RINA-FR-047','2026-05-02T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000006','a1b2c3d4-0002-0000-0000-000000000001','WP-MECH-001','Main Engine Service — Port & Starboard C18','MECHANICAL','Full 5,000-hour service on both Caterpillar C18 main engines. Injector replacement, heat exchanger overhaul, turbocharger inspection, impeller and belt replacement, and alignment check post-service.','ACTIVE',320,45,62000,8500,'Finning CAT','2026-04-20','2026-05-30','2026-04-22',NULL,true,'RINA','RINA-ME-002','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000007','a1b2c3d4-0002-0000-0000-000000000001','WP-MECH-002','Hydraulic Deck Equipment Overhaul','MECHANICAL','Overhaul of all hydraulic systems: anchor windlass, boom vang, sail drive rams, and stabiliser cylinders. New seals and O-rings throughout. Hydraulic fluid change and pressure test to 1.5x working pressure.','SCOPED',180,0,34000,0,'Hydraulic Solutions Ltd','2026-06-01','2026-06-20',NULL,NULL,false,NULL,NULL,'2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000008','a1b2c3d4-0002-0000-0000-000000000001','WP-MECH-003','Generator Service & Load Testing','MECHANICAL','Full service of Northern Lights 60 kW generator set. New fuel filters, impeller, injectors, and coolant. Load bank testing to 100% rated output per RINA requirements. Completed pre-haul-out.','COMPLETE',80,82,14500,14800,'Pendennis Engineering','2026-04-05','2026-04-10','2026-04-05','2026-04-09',true,'RINA','RINA-GEN-001','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000009','a1b2c3d4-0002-0000-0000-000000000001','WP-ELEC-001','Electrical Systems Survey & Shore Power Upgrade','ELECTRICAL','Full electrical survey per RINA requirements including insulation resistance testing of all circuits. Upgrade shore power inlet to 100A/480V three-phase. Replace aged wiring in engine room bilge.','SCOPED',280,0,54000,0,'Pendennis Electrical','2026-05-20','2026-06-25',NULL,NULL,true,'RINA','RINA-EL-003','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000010','a1b2c3d4-0002-0000-0000-000000000001','WP-ELEC-002','Battery Bank Upgrade — 48V Lithium System','ELECTRICAL','Replace 24V lead-acid house bank with new 48V 1,200Ah LiFePO4 system. New Victron Lynx BMS, MultiPlus-II inverter/charger, and DC bus redesign. Owner-requested upgrade for extended passage-making.','DRAFT',200,0,52000,0,NULL,'2026-07-01','2026-07-20',NULL,NULL,false,NULL,NULL,'2026-03-10T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000011','a1b2c3d4-0002-0000-0000-000000000001','WP-RIG-001','Standing Rigging Full Replacement','RIGGING','Full replacement of all standing rigging including main mast shrouds, inner forestay, running backstays, and all Sta-Lok/Seldén terminals. Wire supplied by Seldén UK. Class-required for vessels exceeding 15 years.','ACTIVE',160,12,38500,2400,'Pendennis Rigging','2026-04-25','2026-05-25','2026-04-28',NULL,false,NULL,NULL,'2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000012','a1b2c3d4-0002-0000-0000-000000000001','WP-INT-001','Saloon Joinery & Soft Furnishings Refresh','INTERIOR','Replace saloon and master cabin upholstery. Repair teak overhead delamination (NCR-2026-008). New Karastan wool carpet in passageways. Owner-selected fabrics from Holly Hunt collection.','DRAFT',200,0,42000,0,NULL,'2026-07-01','2026-07-30',NULL,NULL,false,NULL,NULL,'2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000013','a1b2c3d4-0002-0000-0000-000000000001','WP-PAINT-001','Topsides Fairing & Full Repaint','PAINT','Full fairing and repaint of topsides and superstructure. Awlgrip HDT topcoat in Perini white (RAL 9003). Boot-top and cove line in contrasting navy. Includes all cleats, chocks, and hardware reinstatement.','DRAFT',600,0,110000,0,NULL,'2026-06-15','2026-07-20',NULL,NULL,false,NULL,NULL,'2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000014','a1b2c3d4-0002-0000-0000-000000000001','WP-SAFE-001','Safety Equipment Survey & Renewal','SAFETY','Full survey and renewal of all SOLAS safety equipment. Life raft service/replacement, EPIRB replacement (hydrostatic release expired), flare renewal, fire extinguisher hydrostatic test and recharge.','SCOPED',80,0,18500,0,'Ocean Safety Ltd','2026-05-25','2026-06-05',NULL,NULL,true,'RINA','RINA-SF-004','2026-01-20T00:00:00Z'),
  ('a1b2c3d4-0010-0000-0000-000000000015','a1b2c3d4-0002-0000-0000-000000000001','WP-ELEC-003','Navigation Electronics Upgrade','ELECTRICAL','Replace ageing Raymarine chartplotter and AIS transponder. Install Garmin GPSMap 9000 MFD, new B&G Broadband 4G radar, and Icom IC-M605 class-D DSC VHF. Owner-requested scope addition.','DRAFT',60,0,28000,0,NULL,'2026-07-10','2026-07-20',NULL,NULL,false,NULL,NULL,'2026-03-10T00:00:00Z')
INSERT INTO inspection_events (id,project_id,work_package_id,inspection_number,title,inspector_role,inspector_name,scheduled_date,actual_date,result,notes,is_class_inspection,class_item_ref,defect_count,created_at) VALUES
  ('a1b2c3d4-0020-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000001','INSP-CLASS-001','Initial Hull Condition Survey','CLASS_SURVEYOR','Marco Ferretti (RINA)','2026-05-06',NULL,'PENDING',NULL,true,'RINA-5YS-2026',0,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000002','INSP-CLASS-002','Ultrasonic Thickness Gauging — Initial','YARD_QC','Tom Bradley (Pendennis QC)','2026-04-20','2026-04-22','CONDITIONAL_PASS','UT gauging complete. 94% of measurement points within RINA minimum allowance. Two zones identified amidships portside (frames 52-54) reading 7.8mm against 8.5mm minimum — marginal but within 10% allowance per surveyor. Area flagged for increased monitoring and remediation if further wastage found at next gauging.',true,'RINA-UTG-001',1,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000004','INSP-STRUCT-001','MPI Weld Survey — Engine Room Frames','CLASS_SURVEYOR','Marco Ferretti (RINA)','2026-05-12','2026-04-30','FAIL','MPI survey of engine room frames revealed severe corrosion at frames 47-49 portside. Metal loss estimated at 35-40% of original section modulus. Frames cannot be accepted in current condition. NCR raised. Entire WP-STRUCT-002 scope expanded to full frame replacement. Work on hold pending CO approval.',true,'RINA-ST-005',2,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000004','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000005','INSP-STRUCT-002','Frame Corrosion Confirmation — Stations 47-49','CLASS_SURVEYOR','Marco Ferretti (RINA)','2026-05-01','2026-05-01','FAIL','Follow-up inspection with owner''s rep present. Confirmed CRITICAL corrosion at frames 47, 48, and 49 portside bilge. Steel section reduced to approximately 5.1mm from original 8.5mm. Class will not accept repair — full replacement required. Survey programme suspended for this area pending approval of CO-2026-001.',true,'RINA-FR-047',2,'2026-05-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000005','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000006','INSP-MECH-001','Main Engine Room Pre-Service Assessment','OWNERS_REP','Nadir (YAM.Limited)','2026-04-23','2026-04-23','CONDITIONAL_PASS','General engine room condition good. Port C18 in good order — previous 3,000hr service records verified. Starboard C18: coolant sample showed elevated glycol contamination indicating possible internal seal weep. Recommend monitoring at next oil change. Service to proceed as planned.',false,NULL,1,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000006','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000011','INSP-RIG-001','Standing Rigging Condition Assessment','YARD_QC','Tom Bradley (Pendennis QC)','2026-04-29','2026-04-29','FAIL','Rigging survey complete. 15 of 18 terminals acceptable with light surface corrosion only. Main forestay lower swaged terminal: circumferential fatigue cracking visible at swage/wire interface on visual inspection. Structural integrity cannot be confirmed — classified FAIL. Must be replaced before mast re-step. NCR-2026-005 raised.',false,NULL,1,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000007','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000009','INSP-ELEC-001','Shore Power & Earthing Continuity Inspection','CLASS_SURVEYOR','Marco Ferretti (RINA)','2026-04-15','2026-04-15','FAIL','Shore power earthing continuity test failed. Resistance between shore earth and hull bonding system measured at 4.7 ohm — RINA requires <0.1 ohm. Fault traced to corroded earth strap connection at shore power inlet. Presents galvanic corrosion risk and shock hazard. CRITICAL NCR raised. Shore power must not be used until rectified.',true,'RINA-EL-003',1,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000008','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000014','INSP-SAFE-001','Safety Equipment Annual Survey','OWNERS_REP','Nadir (YAM.Limited)','2026-04-10','2026-04-10','CONDITIONAL_PASS','Life rafts: valid hydrostatic service, next due Oct 2027. Fire extinguishers: all within date, 1x CO2 in engine room showing low pressure — replaced. EPIRB: hydrostatic release date expired Dec 2025 — unit otherwise functional but release mechanism must be replaced before departure. Flares: all within date. 406 EPIRB registration current with JRCC UK.',false,NULL,1,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000009','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000003','INSP-HULL-001','Hull & Appendages Pre-Haul Condition','YARD_QC','Tom Bradley (Pendennis QC)','2026-04-05','2026-04-06','PASS','Hull surfaces in good general condition. Antifouling paint approximately 60% effective — heavy growth on port quarter below waterline but structurally sound. All seacocks operational. Shaft seals: port Aquadrive in good condition, stbd showing minor weep — monitored. Rudder bearings: no detectable play. Ready for haul-out.',false,NULL,0,'2026-02-01T00:00:00Z'),
  ('a1b2c3d4-0020-0000-0000-000000000010','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0010-0000-0000-000000000008','INSP-MECH-002','Generator Load Bank Test','OWNERS_REP','Nadir (YAM.Limited)','2026-04-08','2026-04-08','PASS','Northern Lights generator load bank test completed successfully. 100% load sustained for 2 hours with no alarms. Exhaust temperature, coolant temperature, and oil pressure all within limits. Output measured at 61.2 kW at rated speed. RINA certificate issued. Generator approved for class.',false,NULL,0,'2026-02-01T00:00:00Z')
INSERT INTO change_orders (id,project_id,co_number,title,description,trigger_type,status,cost_delta,schedule_delta_days,raised_by,raised_date,defect_record_id,approval_id,created_at) VALUES
  ('a1b2c3d4-0040-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001','CO-2026-001','Frame Replacement Stations 47-49','Full replacement of portside longitudinal frames at stations 47, 48, and 49 per NCR-2026-001. New frames to original scantlings per OEM drawings. RINA class witness required at each stage. Includes steel supply, cutting, fitting, full-penetration welding, PWHT where required, MPI sign-off, and protective coating.','DEFECT_DISCOVERY','PENDING_APPROVAL',47200.00,12,'Nadir','2026-05-02',NULL,NULL,'2026-05-02T08:00:00Z'),
  ('a1b2c3d4-0040-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001','CO-2026-002','Hull Plate Remediation — Amidships Portside','Weld repair and insert plating of amidships portside hull plating zones identified in NCR-2026-003 (thickness gauging). Install new insert plates to restore original scantlings. RINA class witness at completion.','DEFECT_DISCOVERY','PENDING_APPROVAL',31600.00,8,'Nadir','2026-04-23',NULL,NULL,'2026-04-23T09:00:00Z'),
  ('a1b2c3d4-0040-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001','CO-2026-003','Main Forestay Terminal Replacement','Full replacement of main forestay lower swaged terminal assembly per NCR-2026-005. New Sta-Lok open-barrel terminal, Dyform wire, and toggle. Magnetic particle inspection of chainplate at same time. Rigging load test after installation.','DEFECT_DISCOVERY','APPROVED',18900.00,5,'Nadir','2026-04-30',NULL,NULL,'2026-04-30T14:00:00Z'),
  ('a1b2c3d4-0040-0000-0000-000000000004','a1b2c3d4-0002-0000-0000-000000000001','CO-2026-004','Battery Bank Upgrade — 48V LiFePO4 System','Owner-requested upgrade of house battery bank from 24V lead-acid to 48V 1,200Ah LiFePO4 system. Includes Victron Lynx Smart BMS, MultiPlus-II 5kVA inverter/charger, DC bus redesign, and full commissioning.','OWNER_REQUEST','DRAFT',52000.00,0,'Nadir','2026-03-15',NULL,NULL,'2026-03-15T10:00:00Z')
INSERT INTO defect_records (id,project_id,inspection_event_id,work_package_id,ncr_number,title,description,location_on_vessel,severity,status,root_cause,disposition,is_class_defect,class_item_ref,discovered_by,discovered_date,closed_date,cost_impact,schedule_impact_days,change_order_id,created_at) VALUES
  ('a1b2c3d4-0030-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000004','a1b2c3d4-0010-0000-0000-000000000005','NCR-2026-001','CRITICAL Frame Corrosion — Stations 47-49 Portside','Portside longitudinal frames at stations 47, 48, and 49 found with severe through-corrosion in the bilge region. Steel section reduced from original 8.5mm to approximately 5.1mm (40% metal loss). Corrosion is pitting type with active rust, indicating ongoing wastage. RINA class surveyor has confirmed frames cannot be accepted in current condition and full replacement is required for class renewal. Area has been isolated and bilge pump monitoring increased.','Portside Bilge — Frames 47-49, approx 2.1m forward of engine room forward bulkhead','CRITICAL','PENDING_APPROVAL','CORROSION','REPLACE',true,'RINA-FR-047','Marco Ferretti (RINA)','2026-04-30',NULL,47200.00,12,NULL,'2026-04-30T11:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000002','a1b2c3d4-0010-0000-0000-000000000004','NCR-2026-002','Port Deck Fitting Chainplate — Fatigue Cracking','Portside amidships stanchion base chainplate found with visible fatigue cracking along the weld toe during thickness gauging inspection. Crack length approximately 45mm and propagating longitudinally. No immediate structural failure risk but chainplate must be renewed before sea trials. Stanchion removed and area sealed temporarily.','Portside Deck, Amidships — Stanchion Base Chainplate Station 52','HIGH','OPEN','FATIGUE','REPLACE',false,NULL,'Tom Bradley (Pendennis QC)','2026-04-22',NULL,31600.00,8,NULL,'2026-04-22T14:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000002','a1b2c3d4-0010-0000-0000-000000000002','NCR-2026-003','Hull Plate Thickness Below Class Minimum — Amidships Portside','UT thickness gauging identified two zones of hull plating amidships portside reading below RINA minimum allowable: Zone A (frames 52-54) at 7.8mm against 8.5mm minimum, Zone B (frames 55-56) at 7.5mm against 8.5mm minimum. Total affected area approximately 1.8m². RINA surveyor has accepted the finding with a mandatory repair condition — insert plates required before class renewal sign-off.','Portside Hull Plating Amidships — Frames 52-56, approx 1.8m² affected area','HIGH','PENDING_APPROVAL','CORROSION','REPAIR',true,'RINA-UTG-001','Tom Bradley (Pendennis QC)','2026-04-22',NULL,31600.00,8,NULL,'2026-04-22T16:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000004','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000005','a1b2c3d4-0010-0000-0000-000000000006','NCR-2026-004','Starboard C18 Coolant Contamination — Glycol Weep','Coolant sample from starboard Caterpillar C18 shows elevated glycol at 850ppm against baseline of <200ppm, indicating a minor internal coolant path leak. Engine is operational. Possible cause: compression gasket micro-weep or heat exchanger hairline crack. Service team to investigate during planned engine service and replace gaskets as precaution.','Engine Room — Starboard Caterpillar C18, Freshwater Cooling Circuit','MEDIUM','IN_PROGRESS','OTHER','MONITOR',false,NULL,'Nadir (YAM.Limited)','2026-04-23',NULL,NULL,NULL,NULL,'2026-04-23T10:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000005','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000006','a1b2c3d4-0010-0000-0000-000000000011','NCR-2026-005','Main Forestay Lower Terminal — Swage Fatigue Failure','Main forestay lower swaged terminal exhibits circumferential cracking visible to the naked eye at the swage/wire interface. Wire and swage have delaminated at the crack face with approximately 3mm separation at worst point. Crack is propagating under load cycling. Terminal has been condemned by yard rigger. Forestay has been removed from service and mast is supported by temporary stays. Replacement required before mast re-step.','Foredeck — Main Forestay Lower Swaged Terminal at Bowsprit Chainplate','HIGH','CLOSED','FATIGUE','REPLACE',false,NULL,'Tom Bradley (Pendennis QC)','2026-04-29','2026-04-30',18900.00,5,NULL,'2026-04-29T15:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000006','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000008','a1b2c3d4-0010-0000-0000-000000000014','NCR-2026-006','EPIRB Hydrostatic Release Unit Expired','EPIRB hydrostatic release mechanism (Hammar H20) found to have expired Dec 2025. Unit is beyond its stated 2-year replacement interval. The EPIRB 406 MHz transmitter remains functional and registered, but the automatic release mechanism cannot be relied upon. Must be replaced before vessel sails. New Hammar H20 or equivalent to be fitted.','Wheelhouse — EPIRB Cradle, Port Side Aft of Helm Station','MEDIUM','OPEN','WEAR','REPLACE',false,NULL,'Nadir (YAM.Limited)','2026-04-10',NULL,NULL,NULL,NULL,'2026-04-10T09:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000007','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000007','a1b2c3d4-0010-0000-0000-000000000009','NCR-2026-007','Shore Power Earthing Continuity Failure — CRITICAL','Shore power earthing continuity test failed class inspection. Resistance between shore earth pin and hull bonding system measured at 4.7 ohm (RINA maximum 0.1 ohm). Fault isolated to badly corroded earth strap at shore power inlet box — strap fractured and bridged by paint. Presents serious galvanic corrosion risk to underwater metals and electric shock hazard. Shore power must not be connected until fully rectified and re-tested. CRITICAL class finding — prevents class renewal.','Engine Room — Shore Power Inlet Box, Starboard Side Aft Bulkhead','CRITICAL','OPEN','INSTALLATION_ERROR','REPAIR',true,'RINA-EL-003','Marco Ferretti (RINA)','2026-04-15',NULL,52000.00,15,NULL,'2026-04-15T11:00:00Z'),
  ('a1b2c3d4-0030-0000-0000-000000000008','a1b2c3d4-0002-0000-0000-000000000001','a1b2c3d4-0020-0000-0000-000000000005','a1b2c3d4-0010-0000-0000-000000000012','NCR-2026-008','Saloon Overhead Teak Delamination — Water Ingress','Saloon overhead teak lining found partially delaminated above the starboard settee, approximately 400x300mm area. Teak surface lifting and discoloured — evidence of long-term water ingress via coachroof deck fitting above. Fitting bedding compound fully degraded. Interior cosmetic damage only at this stage but will worsen if left untreated through the refit season. Deck fitting to be rebedded as part of WP-INT-001.','Saloon Overhead — Starboard Side Above Settee, Below Coachroof Cleat','LOW','OPEN','MOISTURE_INGRESS','REPAIR',false,NULL,'Captain James Harlow','2026-04-23',NULL,NULL,NULL,NULL,'2026-04-23T08:00:00Z')
INSERT INTO owner_approvals (id,project_id,approval_number,title,description,tier,status,requested_by,requested_date,approver_name,decision_date,decision_notes,change_order_id,cost_amount,deadline,created_at) VALUES
  ('a1b2c3d4-0050-0000-0000-000000000001','a1b2c3d4-0002-0000-0000-000000000001','APPR-2026-001','Approve CO-2026-001: Frame Replacement Stations 47-49','Owner approval required for change order CO-2026-001. Critical structural defect — full frame replacement mandatory for RINA class renewal. Cost impact €47,200 above baseline. Schedule impact +12 days. RINA class surveyor has confirmed no alternative to full replacement. Tier 2 approval required (€10,000–€100,000).','TIER_2','PENDING','Nadir','2026-05-02',NULL,NULL,NULL,'a1b2c3d4-0040-0000-0000-000000000001',47200.00,'2026-05-07','2026-05-02T09:00:00Z'),
  ('a1b2c3d4-0050-0000-0000-000000000002','a1b2c3d4-0002-0000-0000-000000000001','APPR-2026-002','Approve CO-2026-002: Hull Plate Remediation Amidships','Owner approval required for change order CO-2026-002. Class-mandatory hull plate repair identified during UT thickness gauging. Insert plates required before RINA class renewal sign-off. Cost impact €31,600 above baseline. Schedule impact +8 days. Tier 2 approval required.','TIER_2','PENDING','Nadir','2026-04-23',NULL,NULL,NULL,'a1b2c3d4-0040-0000-0000-000000000002',31600.00,'2026-04-28','2026-04-23T10:00:00Z'),
  ('a1b2c3d4-0050-0000-0000-000000000003','a1b2c3d4-0002-0000-0000-000000000001','APPR-2026-003','Approve CO-2026-003: Main Forestay Terminal Replacement','Owner approval required for change order CO-2026-003. Safety-critical — forestay terminal condemned by yard rigger and class surveyor. Mast cannot be re-stepped until replaced. Cost impact €18,900. Schedule impact +5 days. Tier 2 approval required.','TIER_2','APPROVED','Nadir','2026-04-30','Alexander Fontaine','2026-05-01','Approved as an essential safety repair. Please proceed immediately — this is blocking mast re-step and sea trials timeline.','a1b2c3d4-0040-0000-0000-000000000003',18900.00,'2026-05-05','2026-04-30T15:00:00Z')
